--region init

function OverseaManageCatBallLevelUpPopup:InitAction()
    SetButtonAction(self.BtnClose, Bind(self, self.OnClickBtnCloseAction))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnClickFontStyleButtonAction))
    SetButtonAction(self.BtnMax, Bind(self, self.OnClickBtnMaxAction))
    SetButtonAction(self.BtnMin, Bind(self, self.OnClickBtnMinAction))
    SetButtonAction(self.BtnAdd, Bind(self, self.OnClickBtnAddAction))
    SetButtonAction(self.BtnReduce, Bind(self, self.OnClickBtnReduceAction))
end

function OverseaManageCatBallLevelUpPopup:InitData()
    local parameters = self.controller.Argument.parameters
    local data = parameters.data
    self._data = data

    local maxStar = MaidCoffeeUtils.CalcCatRollMaxStar()

    ---@type CatEggDojo
    local catData   = data.catData
    ---@type MaidCoffeeCatRollConfigVo
    local vo        = data.vo
    local star      = math.min(checkNumber(catData.star) + 1, maxStar)
    local maxLevel  = MaidCoffeeUtils.GetMaidCoffeeCatRollStarVo(star).rank
    
    local originLevel = checkNumber(catData.level)
    local nextLevel   = checkNumber(catData.level) + 1
    
    self._catData     = catData
    self._configVo    = vo
    self._originLevel = originLevel
    self._nextLevel   = nextLevel
    self._maxLevel    = maxLevel
end

--endregion


--region logic

function OverseaManageCatBallLevelUpPopup:FreshUI()
    ---刷新等级
    self.TextNumberBeforeLv.text = self._originLevel
    self.TextNumberAfterLv.text  = self._nextLevel
    self:FreshTitle()

    ---刷新能量
    local initEnergy                 = self._configVo.energy
    self.TextNumberBeforeEnergy.text = initEnergy + MaidCoffeeUtils.CalcCatRollAdditionEnergy(self._originLevel)
    self.TextNumberAfterEnergy.text  = initEnergy + MaidCoffeeUtils.CalcCatRollAdditionEnergy(self._nextLevel)

    ---刷新消耗
    local goldNum, consumes = self:GetConsumes()
    self._goldNum, self._consumes = goldNum, consumes
    local isShowGold = goldNum > 0
    KTool.SetActive(self.CommonBtnConsumePop.gameObject, isShowGold)
    if isShowGold then
        UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop, Constants.Currency.GoldId, goldNum)    
    end
    
    UICommonUtils.FillCommonGoodsList(self.CommonGoodsList, consumes, false, false, true, true)
    
    self.InputField.text = self._nextLevel - self._originLevel
end


function OverseaManageCatBallLevelUpPopup:FreshTitle()
    local env = CfUtils.GetLuaScr(self.CommonUITitleNode2, CommonUITitleNode)
    if env then
        env:Refresh(self._configVo.name)
    end
end

--endregion


--region get/set

function OverseaManageCatBallLevelUpPopup:GetConsumes()
    local goldNum  = 0
    local goodsId2Index = {}
    local consumes = {}
    local count = 0
    for level = self._originLevel, self._nextLevel - 1 do
        ---@type MaidCoffeeCatRollLevelVo
        local levelVo    = MaidCoffeeUtils.GetMaidCoffeeCatRollLevelVo(level)
        for i, v in ipairs(levelVo.consumes) do
            local goodsId  = v.goodsId
            local goodsNum = v.goodsNum
            if v.goodsId == Constants.Currency.GoldId then
                goldNum = goldNum + goodsNum
            else
                local index = goodsId2Index[goodsId]
                if index then
                    consumes[index] = consumes[index] or {}
                    consumes[index].goodsNum = consumes[index].goodsNum + goodsNum
                else
                    count = count  + 1
                    goodsId2Index[goodsId] = count
                    
                    table.insert(consumes, clone(v))
                end
            end
        end
    end
    return goldNum, consumes
end

function OverseaManageCatBallLevelUpPopup:UpdateNextLv(deltaLv)
    local lv = math.min(self._maxLevel, self._nextLevel + deltaLv)
    local nextLv = math.max(self._originLevel + 1, lv)
    return self:SetNextLv(nextLv)
end

function OverseaManageCatBallLevelUpPopup:SetNextLv(nextLv)
    local res    = nextLv ~= self._nextLevel
    if res then
        self._nextLevel = nextLv
        self:FreshUI()
    end
    return res
end

--endregion


--region handler

function OverseaManageCatBallLevelUpPopup:OnClickBtnCloseAction()
    CfUtils.DialogBack()
end

function OverseaManageCatBallLevelUpPopup:OnClickFontStyleButtonAction()
    --if true then
    --    local playerCatId = self._catData.id
    --    CfUtils.DialogOpen(Constants.UITypeIds.CultivateLevelUpSecondConfirmPanel, {levelUpType = Constants.UICultivateLevelUpFinishType.CatBallStarUpSuccess, playerCatId = playerCatId, oldStar = 0}, nil, false)
    --    return
    --end
    
    local goldNum, consumes = self._goldNum, self._consumes
    table.insert(consumes, {goodsId = Constants.Currency.GoldId, goodsNum = goldNum})
    local realConsumes, errorTip = GoodsUtils.CheckGoodConsume(consumes)
    if errorTip then
        GameUtils.Toast(errorTip)
        return
    end
    
    local playerCatId = self._catData.id
    local interface = Interfaces.MaidCoffeeCatLevelUp
    local requestData = { playerCatId = playerCatId, targetLevel = self._nextLevel}
    GameUtils.Request(interface, requestData, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local data = response.data
        ---@type CatEggComponent
        local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
        eggComponent:UpdateCatLevel(playerCatId, data.level, data.cafeEnergy)
        
        GoodsUtils.DrawRewards(realConsumes)

        CfUtils.DialogOpen(Constants.UITypeIds.CultivateLevelUpSecondConfirmPanel, {levelUpType = Constants.UICultivateLevelUpFinishType.CatBallLevelUpSuccess, playerCatId = playerCatId, oldLevel = self._originLevel}, nil, false)
        Events.Broadcast(MaidCoffeeConstants.EventNames.LoungeRequestSuccess, interface, requestData)
        
        CfUtils.DialogClose(Constants.UITypeIds.OverseaManageCatballLevelupPopup)
        
    end)
end

function OverseaManageCatBallLevelUpPopup:OnClickBtnMaxAction()
    self:SetNextLv(self._maxLevel)
end

function OverseaManageCatBallLevelUpPopup:OnClickBtnMinAction()
    self:SetNextLv(self._originLevel + 1)
end

function OverseaManageCatBallLevelUpPopup:OnClickBtnAddAction()
    self:UpdateNextLv(1)
end

function OverseaManageCatBallLevelUpPopup:OnClickBtnReduceAction()
    self:UpdateNextLv(-1)
end

--endregion


return OverseaManageCatBallLevelUpPopup
 